// Generated by scripts/build-preload.js. Edit the source modules instead.
'use strict';
// Read only the props backing rendered conversations/messages, without SDK calls.
function readRenderedIM() {
  function props(node, test) {
    let fiber = node?.[Object.keys(node).find((key) => key.startsWith('__reactFiber$'))];
    for (let depth = 0; fiber && depth < 24; depth++, fiber = fiber.return) if (test(fiber.memoizedProps || {})) return fiber.memoizedProps;
    return null;
  }
  const conversations = [], activeIds = new Set();
  for (const node of document.querySelectorAll('[class*="conversation-item--"]')) {
    const value = props(node, (value) => value.sessionInfo?.sessionId);
    if (!value) continue;
    const info = value.sessionInfo, id = String(info.sessionId);
    if (value.activeCid) activeIds.add(String(value.activeCid));
    node.setAttribute('data-xy-session-id', id);
    conversations.push({ id, nickname: node.querySelector('[class*="title--"]')?.textContent.trim() || '', last_text: String(info.summary?.summaryContent || '').slice(0, 500), last_ts: Number(info.summary?.timeStamp) || 0, item_id: String(info.itemInfo?.itemId || '') });
  }
  const chat = document.querySelector('[class*="chat-main--"]');
  const value = props(chat, (value) => typeof value.store?.activeCid === 'string');
  const active = value?.store.activeCid || (activeIds.size === 1 ? [...activeIds][0] : '');
  if (chat) chat.setAttribute('data-xy-session-id', active);
  for (const node of document.querySelectorAll('[class*="message-row--"]')) {
    const value = props(node, (value) => value.message?.messageId && typeof value.isMyMsg === 'boolean');
    if (!value) continue;
    const message = value.message;
    node.setAttribute('data-message-id', String(message.messageId));
    node.setAttribute('data-xy-direction', value.isMyMsg ? 'out' : 'in');
    node.setAttribute('data-xy-text', String(message.content?.text?.text || ''));
    node.setAttribute('data-xy-image', String(message.content?.image?.pics?.[0]?.url || ''));
    const ts = Number(message.createAt || message.timestamp); if (ts) node.setAttribute('data-ts', String(ts));
  }
  return { conversations, active };
}


// im-preload.js
(() => {
'use strict';

/**
 * 注入脚本：运行在 https://www.goofish.com/im 页面内（每个店铺一份）
 *
 * 关键能力：
 *   1. 多店铺同时在线 —— 后台 view 不挂载也能收消息、发消息
 *   2. 收发都不依赖「当前打开的会话」—— 发送时先切到目标会话再发，发完切回
 *   3. 登录态上报
 *
 * ⚠️ 官方页面用 CSS Modules（class 带构建哈希），选择器一律用前缀匹配。
 *    实测结构（2026-10）：
 *      .page-im
 *        .content-container--xxx
 *          .im-main--xxx
 *            .sidebar-container--xxx   ← 会话列表
 *            .chat-main--xxx           ← 对话区
 *     未登录时聊天区为空，登录框在 .login-iframe-wrap--xxx 内 iframe。
 */

const { ipcRenderer, webFrame } = require('electron');
let lastConversations = '', automationBusy = false;
for (const event of ['click', 'keydown', 'paste', 'drop']) document.addEventListener(event, (event) => {
  if (automationBusy && event.isTrusted) { event.preventDefault(); event.stopImmediatePropagation(); }
}, true);
async function refreshRenderedIM() {
  if (!document.querySelector('[class*="conversation-item--"],[class*="message-row--"]')) return;
  const result = await webFrame.executeJavaScriptInIsolatedWorld(0, [{ code: '(' + readRenderedIM.toString() + ')()' }]);
  if (result?.conversations?.length && JSON.stringify(result.conversations) !== lastConversations) { lastConversations = JSON.stringify(result.conversations); ipcRenderer.send('im:sessions', result.conversations); }
}

// ------------------------- 选择器（改版只改这里） -------------------------
const SEL = {
  app:        '[class*="page-im"]',
  imMain:     '[class*="im-main--"]',
  sidebar:    '[class*="sidebar-container--"]',
  chatMain:   '[class*="chat-main--"]',
  convHeader: '[class*="conv-header--"]',

  convItem: [
    '[class*="conv-item"]',
    '[class*="conversation-item"]',
    '[class*="session-item"]',
    '[class*="sidebar-item-wrap"]',
  ],

  messageList: [
    '[class*="message-list"]',
    '[class*="msg-list"]',
    '[class*="chat-message"]',
    '[class*="chat-room"]',
  ],
  messageItem: [
    '[class*="message-row--"]',
    '[class*="message-item"]',
    '[class*="msg-item"]',
    '[data-message-id]',
  ],

  input: [
    '[class*="chat-input"] [contenteditable="true"]',
    '[class*="editor"] [contenteditable="true"]',
    '[class*="input-area"] [contenteditable="true"]',
    '[contenteditable="true"]',
    'textarea',
  ],
  sendBtn: [
    '[class*="send-btn"]',
    '[class*="sendBtn"]',
    '[class*="send-button"]',
    'button[class*="send"]',
  ],

  peerName: [
    '[class*="conv-header--"] [class*="nick"]',
    '[class*="conv-header--"] [class*="name"]',
    '[class*="chat-header"] [class*="nick"]',
  ],

  loginWrap: '[class*="login-iframe-wrap"]',
};

function pick(selectors) {
  const list = Array.isArray(selectors) ? selectors : [selectors];
  for (const s of list) {
    const el = document.querySelector(s);
    if (el) return { el, selector: s };
  }
  return null;
}

function pickAll(selectors) {
  const list = Array.isArray(selectors) ? selectors : [selectors];
  for (const s of list) {
    const found = document.querySelectorAll(s);
    if (found.length) return { list: found, selector: s };
  }
  return null;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

// ------------------------- 登录态 -------------------------

function isLoggedIn() {
  return !!document.querySelector(SEL.app) && !!document.querySelector(SEL.imMain)
    && !document.querySelector(SEL.loginWrap);
}

function reportLoginStatus() {
  ipcRenderer.send('im:login-status', { loggedIn: isLoggedIn() });
}

// ------------------------- 会话 -------------------------

function readSessionId() {
  const rendered = document.querySelector('[class*="chat-main--"][data-xy-session-id]');
  if (rendered) return rendered.getAttribute('data-xy-session-id') || null;
  // 不读取列表中第一条会话的属性；只信任聊天区或明确选中的会话。
  for (const selector of [SEL.convHeader, SEL.chatMain,
    '[aria-selected="true"][data-session-id]', '[data-session-id][class*="active"]',
    '[data-session-id][class*="selected"]']) {
    const element = document.querySelector(selector);
    if (!element) continue;
    for (const key of ['data-session-id', 'data-sessionid', 'data-cid']) {
      const value = element.getAttribute(key);
      if (value) return value;
    }
  }
  try {
    const u = new URL(location.href);
    for (const k of ['sessionId', 'session_id', 'sid', 'cid']) {
      const v = u.searchParams.get(k);
      if (v) return v;
    }
  } catch (_) { /* ignore */ }

  const peer = pick(SEL.peerName);
  return peer ? 'nick:' + peer.el.textContent.trim() : null;
}

function readPeerNick() {
  const peer = pick(SEL.peerName);
  return peer ? peer.el.textContent.trim() : '';
}

/** 会话列表项上的稳定标识（优先 data 属性，其次昵称） */
function convKeyOf(node) {
  if (node.hasAttribute('data-xy-session-id')) return node.getAttribute('data-xy-session-id');
  const attrs = ['data-session-id', 'data-sessionid', 'data-cid', 'data-id'];
  for (const a of attrs) {
    const v = node.getAttribute(a);
    if (v) return v;
  }
  const nameEl = node.querySelector('[class*="nick"], [class*="name"]');
  const name = nameEl ? nameEl.textContent.trim() : node.textContent.trim().slice(0, 20);
  return name ? 'nick:' + name : null;
}

/**
 * 切换到目标会话。
 * sessionId 是我们记录的 key（可能是真 id，也可能是 'nick:xxx'）。
 * @returns {Promise<boolean>}
 */
async function switchToSession(sessionId) {
  await refreshRenderedIM();
  if (!sessionId || String(sessionId).startsWith('nick:')) return false;

  // 已经是当前会话，直接返回
  if (String(readSessionId()) === String(sessionId)) return true;

  const found = pickAll(SEL.convItem);
  if (!found) return false;

  for (const node of found.list) {
    if (String(convKeyOf(node)) !== String(sessionId)) continue;
    node.click();
    // 等会话消息区刷新
    for (let i = 0; i < 20; i++) {
      await sleep(150);
      await refreshRenderedIM();
      if (String(readSessionId()) === String(sessionId)) return true;
    }
    return false; // 无法核验目标时停止，不能向当前买家发送。
  }
  return false;
}

// ------------------------- 消息抽取 -------------------------

const seen = new Set();
const nodeIds = new WeakMap();
const nodeSources = new WeakMap();
const expectedOutgoing = [];
let nodeSequence = 0;
const pageEpoch = Date.now().toString(36) + Math.random().toString(36).slice(2);
let observedSid = null;
let switching = false;
const normalizeText = (text) => String(text || '').trim().replace(/\s+/g, ' ');

function hash(s) {
  let h = 0;
  for (let i = 0; i < s.length; i++) h = ((h << 5) - h + s.charCodeAt(i)) | 0;
  return Math.abs(h).toString(36);
}

function extractOne(node, session) {
  const cls = String(node.className || '');

  const textEl = node.querySelector(
    '[class*="message-content"], [class*="msg-content"], [class*="text"]',
  );
  let text = node.hasAttribute('data-xy-text') ? node.getAttribute('data-xy-text') : (textEl || node).textContent.trim().replace(/\s+/g, ' ');

  const img = node.querySelector('img[class*="content"], img[class*="image"], img[src*="alicdn"]');
  if (img && !textEl) text = '';
  const imageSrc = node.getAttribute('data-xy-image') || img?.src;
  const isSelf = node.getAttribute('data-xy-direction') === 'out' || /(^|\s|--)(right|self|mine|out)(\s|$|--)/.test(cls);

  const idAttr = node.getAttribute('data-message-id') || node.getAttribute('data-id');
  const timestamp = node.getAttribute('data-ts');
  if (!nodeIds.has(node)) nodeIds.set(node, `${pageEpoch}-${++nodeSequence}`);
  const messageId = idAttr || (timestamp
    ? hash(`${session.id}|${timestamp}|${text}|${img ? img.src : ''}|${isSelf}`) : nodeIds.get(node));
  let source = nodeSources.get(node);
  if (isSelf && !source) {
    const pending = expectedOutgoing.find((entry) => !entry.claimed && entry.sessionId === String(session.id)
      && (entry.imageUrl ? sameImage(imageSrc, entry.imageUrl) : normalizeText(entry.text) === text) && Date.now() - entry.ts < 60000);
    if (pending) { pending.claimed = true; source = pending.kind; nodeSources.set(node, source); }
  }

  return {
    messageId,
    ts: Number(node.getAttribute('data-ts')) || Date.now(),
    type: imageSrc && !text ? 2 : 1,
    direction: isSelf ? 'out' : 'in',
    source: isSelf ? source || 'human' : null,
    content: imageSrc && !text ? { imgUrl: imageSrc } : { text },
    user: { id: null, nick: isSelf ? 'me' : readPeerNick() },
  };
}

function scanMessages() {
  if (!isLoggedIn() || switching) return;

  const found = pickAll(SEL.messageItem);
  if (!found) return;

  const session = { id: readSessionId(), withWhoNick: readPeerNick() };
  if (!session.id) return;
  if (session.id !== observedSid) { observedSid = session.id; primeSeen(); return; }

  for (const node of found.list) {
    const msg = extractOne(node, session);
    if (!msg || !msg.messageId) continue;
    if (!msg.content.imgUrl && !msg.content.text) continue;
    if (!msg.content.imgUrl && msg.content.text.length > 3000) continue;

    const key = `${session.id}:${msg.messageId}`;
    if (seen.has(key)) continue;
    seen.add(key);

    ipcRenderer.send('im:message', { session, message: msg });
  }
}

/** 首屏 / 切换会话时，把已有消息标记为已见，避免触发自动回复 */
function primeSeen() {
  const found = pickAll(SEL.messageItem);
  if (!found) return;
  const sid = readSessionId() || '';
  for (const node of found.list) {
    const msg = extractOne(node, { id: sid });
    if (msg && msg.messageId) seen.add(`${sid}:${msg.messageId}`);
  }
}

// ------------------------- 发送 -------------------------

function setInputValue(el, text) {
  el.focus();
  if (el.tagName === 'TEXTAREA') {
    const setter = Object.getOwnPropertyDescriptor(HTMLTextAreaElement.prototype, 'value').set;
    setter.call(el, text);
    el.dispatchEvent(new Event('input', { bubbles: true }));
    return;
  }
  el.innerHTML = '';
  const lines = String(text).split('\n');
  lines.forEach((line, i) => {
    if (i) el.appendChild(document.createElement('br'));
    el.appendChild(document.createTextNode(line));
  });
  el.dispatchEvent(new InputEvent('input', {
    bubbles: true, inputType: 'insertText', data: text,
  }));
}

function clickSend() {
  const btn = pick(SEL.sendBtn);
  if (btn) { btn.el.click(); return true; }

  const input = pick(SEL.input);
  if (!input) return false;
  const opts = {
    key: 'Enter', code: 'Enter', keyCode: 13, which: 13,
    bubbles: true, cancelable: true,
  };
  input.el.dispatchEvent(new KeyboardEvent('keydown', opts));
  input.el.dispatchEvent(new KeyboardEvent('keyup', opts));
  return true;
}

async function sendText(text, { sessionId, requestId, kind }) {
  await refreshRenderedIM();
  const reject = (error, uncertain = false) => ({ ok: false, error, uncertain });
  if (!isLoggedIn()) return reject('未登录');
  if (String(readSessionId()) !== String(sessionId)) return reject('会话已变化，已取消发送');

  const input = pick(SEL.input);
  if (!input) return reject('未找到输入框（选择器需更新）');
  const inputText = () => input.el.tagName === 'TEXTAREA' ? input.el.value : input.el.textContent;
  if (normalizeText(inputText())) return reject('当前有未发送草稿，请先人工处理');
  const before = new Set(Array.from((pickAll(SEL.messageItem) || { list: [] }).list)
    .map((node) => extractOne(node, { id: sessionId }).messageId));

  setInputValue(input.el, text);
  await sleep(150);
  if (String(readSessionId()) !== String(sessionId) || normalizeText(inputText()) !== normalizeText(text)) {
    return reject('会话或草稿已被人工修改，已取消发送');
  }
  if (!await ipcRenderer.invoke('im:can-send', { requestId, sessionId })) {
    if (String(readSessionId()) === String(sessionId) && normalizeText(inputText()) === normalizeText(text)) setInputValue(input.el, '');
    return reject('发送许可已撤销，已取消发送');
  }
  await refreshRenderedIM();
  if (String(readSessionId()) !== String(sessionId) || normalizeText(inputText()) !== normalizeText(text)) {
    return reject('发送前会话或草稿已变化');
  }
  while (expectedOutgoing.length && Date.now() - expectedOutgoing[0].ts > 60000) expectedOutgoing.shift();
  expectedOutgoing.push({ sessionId: String(sessionId), text, kind, ts: Date.now(), claimed: false });
  if (!clickSend()) return reject('未找到发送按钮');
  // 点击和乐观插入气泡不等于成功；必须看到新消息明确的已发送/已读状态。
  for (let attempt = 0; attempt < 40; attempt++) {
    await sleep(250);
    await refreshRenderedIM();
    if (String(readSessionId()) !== String(sessionId)) return reject('发送后会话变化，请人工核对', true);
    for (const node of (pickAll(SEL.messageItem) || { list: [] }).list) {
      const message = extractOne(node, { id: sessionId });
      if (before.has(message.messageId) || message.direction !== 'out'
          || normalizeText(message.content.text) !== normalizeText(text)) continue;
      const statusNode = node.querySelector('[class*="status"], [class*="read-state"], [data-status]');
      const state = node.getAttribute('data-status') || (statusNode && statusNode.getAttribute('data-status')) || '';
      const label = statusNode ? statusNode.textContent.trim() : '';
      if (/failed|error/i.test(state) || /失败|重试/.test(label)) return reject('页面提示发送失败，请核对后处理', true);
      if (/^(sent|success|delivered|read)$/i.test(state) || /^(已发送|已送达|送达|已读|未读)$/.test(label)) {
        scanMessages();
        return { ok: true, messageId: message.messageId, uncertain: false };
      }
    }
  }
  return reject('已尝试发送，但未获得明确成功状态，请人工核对', true);
}

/**
 * 跨会话发送：先切到目标会话，再发，发完切回原会话。
 * 这样后台店铺也能回复任意买家，而不需要人工先点开那个会话。
 */
let sendQueue = Promise.resolve();

function sameImage(candidate, expected) {
  try {
    const a = new URL(candidate), b = new URL(expected);
    return a.hostname === b.hostname && (a.pathname === b.pathname || a.pathname.startsWith(b.pathname + '_'));
  } catch (_) { return false; }
}
function visible(node) { const rect = node?.getBoundingClientRect(); return !!rect && rect.width > 0 && rect.height > 0 && getComputedStyle(node).visibility !== 'hidden'; }

async function sendImage(reply, { sessionId, requestId, kind }) {
  await refreshRenderedIM();
  const reject = (error, uncertain = false) => ({ ok: false, error, uncertain });
  if (!isLoggedIn() || String(readSessionId()) !== String(sessionId)) return reject('登录或目标会话已变化');
  const input = pick(SEL.input)?.el;
  if (!input) return reject('聊天输入区尚未加载');
  if (normalizeText(input.tagName === 'TEXTAREA' ? input.value : input.textContent)
      || Array.from(document.querySelectorAll('[class*="upload-preview"],[class*="image-preview"],[data-chat-image-preview]')).some(visible)) return reject('聊天区有人工草稿或待发送图片，请先处理');
  const before = new Set(Array.from(pickAll(SEL.messageItem)?.list || []).map((node) => extractOne(node, { id: sessionId }).messageId));
  if (!await ipcRenderer.invoke('im:can-send', { requestId, sessionId })) return reject('图片发送许可已撤销');
  const uploaded = await ipcRenderer.invoke('im:upload-image', { requestId, sessionId, assetId: reply.assetId });
  if (!uploaded?.ok) return uploaded || reject('图片上传未确认', true);
  if (String(readSessionId()) !== String(sessionId)) return reject('图片上传后会话已变化，请核对', true);
  expectedOutgoing.push({ sessionId: String(sessionId), imageUrl: uploaded.imageUrl, kind, ts: Date.now(), claimed: false });
  await sleep(200);
  const candidates = () => Array.from(pickAll(SEL.messageItem)?.list || []).filter((node) => {
    const message = extractOne(node, { id: sessionId });
      return !before.has(message.messageId) && message.direction === 'out' && sameImage(node.getAttribute('data-xy-image') || node.querySelector('img')?.src, uploaded.imageUrl);
  });
  // 官方页面可能上传后立即发送；仅有明确的预览弹窗时才点击一次发送。
  const preview = Array.from(document.querySelectorAll('[class*="upload-preview"],[class*="image-preview"],[data-chat-image-preview]'))
    .find((node) => visible(node) && Array.from(node.querySelectorAll('img')).some((image) => sameImage(image.src, uploaded.imageUrl)));
  if (!candidates().length && preview) {
    const send = Array.from((preview.closest('[role="dialog"],.ant-modal') || preview).querySelectorAll('button'))
      .find((button) => visible(button) && /^(发送|确认发送)$/.test(button.textContent.trim()));
    if (!send || !await ipcRenderer.invoke('im:can-send', { requestId, sessionId })) return reject('图片预览尚不能确认发送，请人工核对', true);
    send.click();
  }
    for (let attempt = 0; attempt < 40; attempt++) {
      await refreshRenderedIM();
    if (String(readSessionId()) !== String(sessionId)) return reject('图片发送后会话变化，请核对', true);
    const nodes = candidates(); if (nodes.length > 1) return reject('存在多条同图消息，请核对本次图片投递', true);
    for (const node of nodes) {
      const status = node.querySelector('[class*="status"],[class*="read-state"],[data-status]');
      const state = node.getAttribute('data-status') || status?.getAttribute('data-status') || '', label = status?.textContent.trim() || '';
      if (/failed|error/i.test(state) || /失败|重试/.test(label)) return reject('页面提示图片发送失败，请核对', true);
      if (/^(sent|success|delivered|read)$/i.test(state) || /^(已发送|已送达|送达|已读|未读)$/.test(label)) {
        nodeSources.set(node, kind); scanMessages(); return { ok: true, uncertain: false, messageId: extractOne(node, { id: sessionId }).messageId };
      }
    }
    await sleep(250);
  }
  return reject('未确认图片已送达，请先核对，卡密保持占用', true);
}

function enqueueSend(task) {
  const result = sendQueue.then(task);
  sendQueue = result.catch((e) => {
    console.error('[xy-inject] send task failed', e);
  });
  return result;
}

ipcRenderer.on('inject:send', (_e, payload) => {
  const { sessionId, reply, requestId } = payload || {};
  const report = (result) => ipcRenderer.send('im:send-result', {
    requestId, sessionId, kind: reply && reply.kind, ...result,
  });
  if (!requestId || !sessionId || String(sessionId).startsWith('nick:') || !reply || !reply.content) {
    report({ ok: false, uncertain: false, error: '缺少可核验的发送请求' });
    return;
  }

  enqueueSend(async () => {
    await refreshRenderedIM();
    const origin = readSessionId();
    let switched = false;

    try {
      if (sessionId && String(sessionId) !== String(origin)) {
        switching = true;
        switched = await switchToSession(sessionId);
        if (!switched) {
          report({ ok: false, uncertain: false, error: `无法确认目标会话 ${sessionId}` });
          return;
        }
        await sleep(400); // 等消息区渲染完成
        observedSid = readSessionId();
        primeSeen();
        switching = false;
      }

      automationBusy = true;
      const res = reply.type === 'image' ? await sendImage(reply, { sessionId, requestId, kind: reply.kind })
        : await sendText(reply.content, { sessionId, requestId, kind: reply.kind });
      report(res);
    } catch (error) {
      report({ ok: false, uncertain: true, error: error.message });
    } finally {
      // 切回原会话，避免打扰正在看界面的人
      if (switched && origin && String(readSessionId()) === String(sessionId)) {
        switching = true;
        await sleep(300);
        await switchToSession(origin);
        observedSid = readSessionId();
        primeSeen();
      }
      switching = false;
      automationBusy = false;
    }
  });
});
ipcRenderer.on('inject:history', (_event, { requestId, sessionId }) => enqueueSend(async () => {
  let origin, switched = false;
  try {
    await refreshRenderedIM(); origin = readSessionId();
    const input = pick(SEL.input)?.el;
    if (origin !== sessionId && normalizeText(input?.value || input?.textContent)) throw new Error('主机聊天区有人工草稿，请稍后读取');
    automationBusy = true;
    if (origin !== sessionId) { switching = true; switched = await switchToSession(sessionId); if (!switched) throw new Error('无法打开目标会话，请在主机登录后重试'); await sleep(500); }
    await refreshRenderedIM();
    if (String(readSessionId()) !== String(sessionId)) throw new Error('目标会话已改变');
    const messages = Array.from(pickAll(SEL.messageItem)?.list || []).slice(-100).map((node) => extractOne(node, { id: sessionId })).map((message) => ({ id: message.messageId, text: message.content.text || '[图片]', direction: message.direction, type: message.type, ts: message.ts }));
    ipcRenderer.send('im:history-result', { requestId, sessionId, ok: true, messages });
  } catch (error) { ipcRenderer.send('im:history-result', { requestId, sessionId, ok: false, error: error.message }); }
  finally { if (switched && origin && String(readSessionId()) === String(sessionId)) await switchToSession(origin); switching = false; automationBusy = false; observedSid = null; }
}));

// ------------------------- 启动 -------------------------

let observer = null;
let watchTimer = null;

function boot() {
  reportLoginStatus();
  observedSid = readSessionId();
  primeSeen();

  const root = pick(SEL.chatMain) || pick(SEL.imMain) || { el: document.body };

  observer = new MutationObserver(() => {
    clearTimeout(boot._t);
    boot._t = setTimeout(scanMessages, 250);
  });
  observer.observe(document.body, { childList: true, subtree: true, characterData: true });

  // 会话切换 → 重新 primeSeen
  let lastSid = readSessionId();
  let lastLogin = isLoggedIn();
  watchTimer = setInterval(async () => {
    try { await refreshRenderedIM(); } catch (_) {}
    const sid = readSessionId();
    if (sid && sid !== lastSid) {
      lastSid = sid;
      observedSid = null;
    }
    const nowLogin = isLoggedIn();
    if (nowLogin !== lastLogin) {
      lastLogin = nowLogin;
      reportLoginStatus();
      if (nowLogin) observedSid = null;
    }
  }, 1000);

  console.log('[xy-inject] ready | chatRoot =', root.selector || 'body',
    '| messageItem =', (pickAll(SEL.messageItem) || {}).selector || 'not-found',
    '| loggedIn =', isLoggedIn());
}

if (document.readyState === 'loading') {
  document.addEventListener('DOMContentLoaded', boot);
} else {
  boot();
}

// 仅在隔离的 preload 世界共享；构建脚本随后合并页面操作和任务模块。
globalThis.__xyAutomation = { readSessionId, switchToSession, enqueue: enqueueSend };

})();

// page-actions.js
(() => {
'use strict';

/**
 * 官方页面 UI 自动化（发送商品卡片 / 拉黑）
 *
 * ⚠️ 重要前提
 *   这两个动作都必须在「已登录 + 已打开某个会话」的官方页面上执行。
 *   未登录时聊天区是空的，任何选择器都探不到。
 *
 * 设计原则：
 *   1. 选择器集中在 PAGE_UI 里，官方改版只改这里
 *   2. 每一步都有「找不到就明确报错」，绝不静默发错内容
 *   3. 操作前先确认当前会话正确，避免发到错误买家
 *
 * 未登录时本模块的所有方法都会返回 { ok:false, error:'未登录' }。
 */

const { ipcRenderer } = require('electron');

/* ------------------------- 官方页面选择器（改版改这里） ------------------------- */
const PAGE_UI = {
  // 已登录判断
  loginWrap: '[class*="login-iframe-wrap"]',

  // 会话区
  chatMain: '[class*="chat-main--"]',
  convHeader: '[class*="conv-header--"]',
  convItem: [
    '[class*="conv-item"]',
    '[class*="conversation-item"]',
    '[class*="session-item"]',
    '[class*="sidebar-item-wrap"]',
  ],

  // 输入区
  input: [
    '[class*="chat-input"] [contenteditable="true"]',
    '[class*="editor"] [contenteditable="true"]',
    '[contenteditable="true"]',
    'textarea',
  ],
  sendBtn: [
    '[class*="send-btn"]',
    '[class*="sendBtn"]',
    '[class*="send-button"]',
    'button[class*="send"]',
  ],

  // 工具栏（发送商品入口常见形态）
  toolbar: [
    '[class*="toolbar"]',
    '[class*="chat-tool"]',
    '[class*="action-bar"]',
    '[class*="editor-tool"]',
  ],
  // 工具栏里的「商品」按钮：文字或图标名含商品/宝贝
  productBtn: [
    '[class*="product"]',
    '[class*="goods"]',
    '[title*="商品"]',
    '[title*="宝贝"]',
    '[aria-label*="商品"]',
  ],

  // 商品选择弹层
  productDlg: [
    '[class*="product-dialog"]',
    '[class*="goods-dialog"]',
    '[class*="product-select"]',
    '[class*="ant-modal"]',
    '[role="dialog"]',
  ],
  productItem: [
    '[class*="product-item"]',
    '[class*="goods-item"]',
    '[class*="product-card"]',
    '[class*="item-card"]',
  ],
  dlgConfirm: [
    '[class*="confirm"]',
    'button[class*="primary"]',
    '[class*="ok-btn"]',
  ],

  // 更多菜单（拉黑入口）
  moreBtn: [
    '[class*="more"]',
    '[title*="更多"]',
    '[aria-label*="更多"]',
    '[class*="setting"]',
  ],
  // 拉黑菜单项
  blockItem: [
    '[class*="block"]',
    '[class*="black"]',
  ],
  // 确认弹窗
  confirmBtn: [
    '[class*="confirm"]',
    'button[class*="primary"]',
    '[class*="ok-btn"]',
    '[class*="sure"]',
  ],
};

/* ------------------------- 工具函数 ------------------------- */

function pick(selectors) {
  const list = Array.isArray(selectors) ? selectors : [selectors];
  for (const s of list) {
    try {
      const el = document.querySelector(s);
      if (el) return { el, selector: s };
    } catch (_) { /* 非法选择器忽略 */ }
  }
  return null;
}

function pickAll(selectors) {
  const list = Array.isArray(selectors) ? selectors : [selectors];
  for (const s of list) {
    try {
      const found = document.querySelectorAll(s);
      if (found.length) return { list: Array.from(found), selector: s };
    } catch (_) { /* ignore */ }
  }
  return null;
}

/** 元素是否可见可点 */
function visible(el) {
  if (!el) return false;
  const r = el.getBoundingClientRect();
  if (r.width < 2 || r.height < 2) return false;
  const st = getComputedStyle(el);
  return st.display !== 'none' && st.visibility !== 'hidden' && Number(st.opacity) > 0.05;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/** 等待某个条件成立 */
async function waitFor(fn, timeoutMs = 5000, stepMs = 150) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    try { const v = fn(); if (v) return v; } catch (_) { /* ignore */ }
    await sleep(stepMs);
  }
  return null;
}

/**
 * 判断页面处于三种状态之一：
 *   loading     —— 页面还没真正加载（连 page-im 都没有）
 *   logged-out  —— 有登录框
 *   logged-in   —— 有 page-im 且无登录框
 *
 * 区分 loading 很关键：否则页面空白时会被误判成「已登录」。
 */
function pageState() {
  const hasApp = !!document.querySelector('[class*="page-im"]')
    || document.body.innerText.trim().length > 100;
  if (!hasApp) return 'loading';
  return document.querySelector(PAGE_UI.loginWrap) ? 'logged-out' : 'logged-in';
}

function isLoggedIn() {
  return pageState() === 'logged-in';
}

/** 统一的可操作性检查；返回 null 表示可以继续 */
function guardReady() {
  const st = pageState();
  if (st === 'loading') return { ok: false, error: '页面还在加载，请稍后再试', retryable: true };
  if (st === 'logged-out') return { ok: false, error: '未登录，请先在页面上扫码登录闲鱼' };
  return null;
}

function readPeerNick() {
  const el = pick([
    '[class*="conv-header--"] [class*="nick"]',
    '[class*="conv-header--"] [class*="name"]',
    '[class*="chat-header"] [class*="nick"]',
  ]);
  return el ? el.el.textContent.trim() : '';
}

/* ------------------------- 切会话 ------------------------- */

function convKeyOf(node) {
  for (const a of ['data-session-id', 'data-sessionid', 'data-cid', 'data-id']) {
    const v = node.getAttribute(a);
    if (v) return v;
  }
  const nameEl = node.querySelector('[class*="nick"], [class*="name"]');
  const name = nameEl ? nameEl.textContent.trim() : node.textContent.trim().slice(0, 20);
  return name ? 'nick:' + name : null;
}

async function switchToSession(sessionId) {
  return !!globalThis.__xyAutomation && globalThis.__xyAutomation.switchToSession(sessionId);
}

function currentSessionMatches(sessionId) {
  return sessionId && !String(sessionId).startsWith('nick:') && globalThis.__xyAutomation
    && String(globalThis.__xyAutomation.readSessionId()) === String(sessionId);
}

/* ------------------------- 发送商品卡片 ------------------------- */

/**
 * 在官方页面打开「发送商品」入口，选一个商品发出。
 *
 * @param {object} opts
 * @param {string} opts.sessionId   目标会话（空=当前会话）
 * @param {string} opts.itemId      商品ID
 * @param {string} [opts.keyword]   商品标题关键词（用于在选择弹层里定位）
 */
async function sendProduct({ sessionId, itemId, keyword }) {
  const notReady = guardReady();
  if (notReady) return notReady;
  if (!itemId) return { ok: false, error: '缺少商品ID' };
  sessionId = sessionId || globalThis.__xyAutomation.readSessionId();
  if (!sessionId || String(sessionId).startsWith('nick:')) return { ok: false, error: '无法核验目标会话，请人工操作' };

  const origin = readPeerNick();

  // 1. 切会话
  if (sessionId) {
    const ok = await switchToSession(sessionId);
    if (!ok) return { ok: false, error: `找不到会话 ${sessionId}` };
    await sleep(500);
  }

  // 2. 找工具栏的「商品」按钮
  let productBtn = null;

  // 2a. 先在工具栏范围内找
  const toolbar = pick(PAGE_UI.toolbar);
  if (toolbar) {
    productBtn = pick(PAGE_UI.productBtn.filter((s) => {
      try { return !!toolbar.el.querySelector(s); } catch (_) { return false; }
    }).map((s) => `:scope ${s}`));
  }

  // 2b. 全局兜底找
  if (!productBtn) productBtn = pick(PAGE_UI.productBtn);

  if (!productBtn || !visible(productBtn.el)) {
    return {
      ok: false,
      error: '找不到「发送商品」按钮（官方页面结构可能变了，或当前会话不支持）',
      needManual: true,
    };
  }

  productBtn.el.click();
  await sleep(800);

  // 3. 等商品选择弹层出现
  const dlg = await waitFor(() => pick(PAGE_UI.productDlg), 4000);
  if (!dlg) {
    return { ok: false, error: '商品选择弹层没出现', needManual: true };
  }

  // 4. 在弹层里找目标商品
  const items = pickAll(PAGE_UI.productItem);
  if (!items) {
    return { ok: false, error: '商品列表为空或结构不识别', needManual: true };
  }

  let target = null;
  for (const node of items.list) {
    const txt = node.textContent || '';
    const attr = node.getAttribute('data-item-id') || node.getAttribute('data-id') || '';
    if (attr && String(attr).includes(String(itemId))) { target = node; break; }
    if (keyword && txt.includes(keyword)) { target = node; break; }
    if (txt.includes(String(itemId))) { target = node; break; }
  }

  if (!target) {
    // 关掉弹层（按 Esc）
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
    return {
      ok: false,
      error: `商品列表里找不到 ${itemId}${keyword ? ' / ' + keyword : ''}（可能需要先滚动加载）`,
      needManual: true,
    };
  }

  // 5. 选中并确认发送
  if (!currentSessionMatches(sessionId)) return { ok: false, error: '会话已变化，已取消发送商品' };
  target.click();
  await sleep(500);

  // 有些页面选完直接发送，有些要再点确认
  const confirm = pick(PAGE_UI.dlgConfirm);
  if (confirm && visible(confirm.el)) {
    if (!currentSessionMatches(sessionId)) return { ok: false, error: '会话已变化，已取消确认' };
    confirm.el.click();
    await sleep(600);
  }

  return {
    ok: true,
    itemId,
    peerNick: readPeerNick() || origin,
    note: '已触发发送，请确认买家是否收到商品卡片',
  };
}

/* ------------------------- 拉黑 / 解除拉黑 ------------------------- */

/**
 * 拉黑当前会话的买家。
 *
 * 路径：会话头部「更多」→「拉黑」→ 确认
 *
 * @param {object} opts
 * @param {string} opts.sessionId
 * @param {boolean} [opts.unblock]  true = 解除拉黑
 */
async function setBlocked({ sessionId, unblock = false }) {
  const notReady = guardReady();
  if (notReady) return notReady;
  sessionId = sessionId || globalThis.__xyAutomation.readSessionId();
  if (!sessionId || String(sessionId).startsWith('nick:')) return { ok: false, error: '无法核验目标会话，请人工操作' };

  if (sessionId) {
    const ok = await switchToSession(sessionId);
    if (!ok) return { ok: false, error: `找不到会话 ${sessionId}` };
    await sleep(500);
  }

  const peerNick = readPeerNick();

  // 1. 点「更多」菜单
  const moreBtn = pick(PAGE_UI.moreBtn);
  if (!moreBtn || !visible(moreBtn.el)) {
    return {
      ok: false,
      error: '找不到会话头部的「更多」按钮（官方页面结构可能变了）',
      needManual: true,
    };
  }
  moreBtn.el.click();
  await sleep(700);

  // 2. 在菜单里找「拉黑 / 解除拉黑」
  const menuItems = Array.from(document.querySelectorAll(
    '[class*="menu"] li, [class*="dropdown"] li, [role="menuitem"], [class*="menu-item"]',
  )).filter(visible);

  const wantText = unblock ? /解除|取消拉黑|移出/ : /拉黑|加入黑名单|屏蔽/;
  let blockEntry = null;
  for (const el of menuItems) {
    if (wantText.test(el.textContent || '')) { blockEntry = el; break; }
  }

  // 兜底：用 class 找
  if (!blockEntry) {
    const byClass = pick(PAGE_UI.blockItem);
    if (byClass && visible(byClass.el)) blockEntry = byClass.el;
  }

  if (!blockEntry) {
    document.dispatchEvent(new KeyboardEvent('keydown', { key: 'Escape', keyCode: 27, bubbles: true }));
    return {
      ok: false,
      error: `菜单里找不到「${unblock ? '解除拉黑' : '拉黑'}」选项`,
      needManual: true,
    };
  }

  if (!currentSessionMatches(sessionId)) return { ok: false, error: '会话已变化，已取消操作' };
  blockEntry.click();
  await sleep(700);

  // 3. 确认弹窗
  const confirm = pick(PAGE_UI.confirmBtn);
  if (confirm && visible(confirm.el)) {
    if (!currentSessionMatches(sessionId)) return { ok: false, error: '会话已变化，已取消确认' };
    confirm.el.click();
    await sleep(600);
  }

  return {
    ok: true,
    peerNick,
    action: unblock ? 'unblock' : 'block',
    note: '已执行，请在页面上确认买家状态',
  };
}

/* ------------------------- 诊断：探测页面结构 ------------------------- */

/**
 * 探测当前页面有哪些可用元素。
 * 未登录时会返回 loggedIn:false，这是正常现象。
 */
function diagnose() {
  const state = pageState();
  const out = {
    state,
    loggedIn: state === 'logged-in',
    url: location.href,
    bodyLen: document.body.innerText.trim().length,
    peerNick: readPeerNick(),
    found: {},
  };

  if (state === 'loading') {
    out.hint = '页面还在加载（还没出现 page-im 容器），请稍等再诊断。';
    return out;
  }
  if (state === 'logged-out') {
    out.hint = '未登录：聊天区为空，选择器无法探测。请先扫码登录。';
    return out;
  }

  const checks = {
    chatMain: PAGE_UI.chatMain,
    convHeader: PAGE_UI.convHeader,
    input: PAGE_UI.input,
    sendBtn: PAGE_UI.sendBtn,
    toolbar: PAGE_UI.toolbar,
    productBtn: PAGE_UI.productBtn,
    moreBtn: PAGE_UI.moreBtn,
  };
  for (const [k, sel] of Object.entries(checks)) {
    const r = pick(sel);
    out.found[k] = r ? { selector: r.selector, text: (r.el.textContent || '').trim().slice(0, 20) } : null;
  }

  // 列出所有可见按钮，帮助人工判断
  out.visibleButtons = Array.from(document.querySelectorAll('button, [role="button"], [class*="iconfont"]'))
    .filter(visible)
    .slice(0, 30)
    .map((e) => ({
      tag: e.tagName,
      cls: String(e.className).slice(0, 50),
      title: e.getAttribute('title') || '',
      txt: (e.textContent || '').trim().slice(0, 12),
    }));

  out.convCount = (pickAll(PAGE_UI.convItem) || { list: [] }).list.length;
  return out;
}

/* ------------------------- IPC ------------------------- */

ipcRenderer.on('action:send-product', async (_e, payload) => {
  const requestId = payload && payload.requestId;
  let res;
  try {
    res = await globalThis.__xyAutomation.enqueue(() => sendProduct(payload || {}));
  } catch (e) {
    res = { ok: false, error: String(e && e.message || e) };
  }
  ipcRenderer.send('action:result', { action: 'sendProduct', requestId, ...res });
});

ipcRenderer.on('action:set-blocked', async (_e, payload) => {
  const requestId = payload && payload.requestId;
  let res;
  try {
    res = await globalThis.__xyAutomation.enqueue(() => setBlocked(payload || {}));
  } catch (e) {
    res = { ok: false, error: String(e && e.message || e) };
  }
  ipcRenderer.send('action:result', { action: 'setBlocked', requestId, ...res });
});

ipcRenderer.on('action:diagnose', () => {
  ipcRenderer.send('action:diagnose-result', diagnose());
});

// 暴露给 devtools 调试用
window.__xyAction = { sendProduct, setBlocked, diagnose };

})();

// task-runner.js
(() => {
'use strict';

/**
 * 高风险任务执行器（注入到官方页面）
 *
 * 包含：
 *   - polish  擦亮（我的闲鱼 → 商品 → 擦亮按钮）
 *   - rate    自动评价（订单详情 → 评价）
 *
 * ⚠️ 这个脚本会点击官方页面的真实按钮。
 *    平台可能检测到自动化行为，风险由使用者承担。
 *
 * 频率限制（内置，不可通过配置关闭）：
 *   - 擦亮：每小时最多 1 次，每天最多 1 次成功
 *   - 评价：每分钟最多 3 条
 */

const { ipcRenderer } = require('electron');

const SEL = {
  // 商品列表里的「擦亮」按钮
  polishBtn: [
    '[class*="polish"]',
    '[class*="refresh"]',
    'button[class*="shine"]',
    '[title*="擦亮"]',
    '[aria-label*="擦亮"]',
  ],
  // 商品卡片
  productCard: [
    '[class*="item-card"]',
    '[class*="goods-card"]',
    '[data-item-id]',
    'a[href*="item?id="]',
  ],
  // 评价相关
  rateBtn: [
    '[class*="rate"]',
    '[class*="comment"]',
    '[title*="评价"]',
  ],
  rateTextarea: [
    'textarea[class*="content"]',
    'textarea',
    '[contenteditable="true"]',
  ],
  rateSubmit: [
    'button[class*="submit"]',
    'button[class*="confirm"]',
    '[class*="submit-btn"]',
  ],
};

function pick(selectors) {
  const list = Array.isArray(selectors) ? selectors : [selectors];
  for (const s of list) {
    try {
      const el = document.querySelector(s);
      if (el) return { el, selector: s };
    } catch (_) { /* ignore */ }
  }
  return null;
}

function pickAll(selectors) {
  const list = Array.isArray(selectors) ? selectors : [selectors];
  for (const s of list) {
    try {
      const found = document.querySelectorAll(s);
      if (found.length) return { list: Array.from(found), selector: s };
    } catch (_) { /* ignore */ }
  }
  return null;
}

function visible(el) {
  if (!el) return false;
  const r = el.getBoundingClientRect();
  if (r.width < 2 || r.height < 2) return false;
  const st = getComputedStyle(el);
  return st.display !== 'none' && st.visibility !== 'hidden' && Number(st.opacity) > 0.05;
}

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

/* ------------------------------ 频率限制 ------------------------------ */

const lastRun = { polish: 0, rate: [] };
const POLISH_MIN_INTERVAL = 3600_000;   // 1 小时
const RATE_WINDOW = 60_000;             // 1 分钟
const RATE_MAX = 3;

function canPolish() {
  return Date.now() - lastRun.polish >= POLISH_MIN_INTERVAL;
}

function canRate() {
  const now = Date.now();
  lastRun.rate = lastRun.rate.filter((t) => now - t < RATE_WINDOW);
  return lastRun.rate.length < RATE_MAX;
}

/* ------------------------------ 擦亮 ------------------------------ */

async function runPolish() {
  if (!canPolish()) {
    return { ok: false, reason: '擦亮频率限制：每小时最多 1 次' };
  }

  const btn = pick(SEL.polishBtn);
  if (!btn || !visible(btn.el)) {
    return {
      ok: false,
      reason: '找不到「擦亮」按钮。可能原因：不在商品管理页、未登录、或页面结构已变。',
      needManual: true,
    };
  }

  // 只点一次（避免误点全部商品触发批量擦亮）
  btn.el.click();
  lastRun.polish = Date.now();
  await sleep(1500);

  // 检查是否有确认弹窗
  const confirm = pick(['[class*="confirm"] button[class*="primary"]', 'button[class*="sure"]']);
  if (confirm && visible(confirm.el)) {
    confirm.el.click();
    await sleep(800);
  }

  return { ok: true, count: 1, reason: '已点击擦亮按钮' };
}

/** 批量擦亮（逐个商品点，带间隔） */
async function runPolishBatch() {
  if (!canPolish()) {
    return { ok: false, reason: '擦亮频率限制：每小时最多 1 次' };
  }

  const cards = pickAll(SEL.productCard);
  if (!cards) {
    return { ok: false, reason: '找不到商品列表', needManual: true };
  }

  let count = 0;
  const maxPerRun = 20; // 单次最多擦 20 个，防止一次点太多触发风控

  for (const card of cards.list.slice(0, maxPerRun)) {
    const btn = pick(SEL.polishBtn);
    if (!btn || !visible(btn.el)) continue;
    btn.el.click();
    count++;
    // 每个之间 2-4 秒随机间隔（模拟人工）
    await sleep(2000 + Math.random() * 2000);
  }

  if (count > 0) lastRun.polish = Date.now();
  return {
    ok: count > 0,
    count,
    reason: count > 0 ? `已擦亮 ${count} 个商品` : '没有可擦亮的商品',
  };
}

/* ------------------------------ 自动评价 ------------------------------ */

async function runRate({ text } = {}) {
  if (!canRate()) {
    return { ok: false, reason: '评价频率限制：每分钟最多 3 条' };
  }

  const btn = pick(SEL.rateBtn);
  if (!btn || !visible(btn.el)) {
    return {
      ok: false,
      reason: '找不到「评价」按钮。请在订单页打开待评价订单。',
      needManual: true,
    };
  }
  btn.el.click();
  await sleep(1000);

  // 填评价内容
  const tpl = String(text || '东西不错，发货很快，好评~');
  const ta = pick(SEL.rateTextarea);
  if (ta && visible(ta.el)) {
    if (ta.el.tagName === 'TEXTAREA') {
      ta.el.value = tpl;
      ta.el.dispatchEvent(new Event('input', { bubbles: true }));
    } else {
      ta.el.textContent = tpl;
      ta.el.dispatchEvent(new InputEvent('input', { bubbles: true }));
    }
    await sleep(500);
  }

  // 提交
  const submit = pick(SEL.rateSubmit);
  if (!submit || !visible(submit.el)) {
    return { ok: false, reason: '找不到提交按钮', needManual: true };
  }
  submit.el.click();
  lastRun.rate.push(Date.now());
  await sleep(1200);

  // 二次确认
  const confirm = pick(['[class*="confirm"] button[class*="primary"]', 'button[class*="sure"]']);
  if (confirm && visible(confirm.el)) {
    confirm.el.click();
    await sleep(600);
  }

  return { ok: true, reason: '已提交评价' };
}

/* ------------------------------ IPC ------------------------------ */

ipcRenderer.on('task:run', async (_e, { taskId, payload, requestId }) => {
  let result;
  try {
    if (taskId === 'polish') {
      result = await globalThis.__xyAutomation.enqueue(() => payload && payload.batch ? runPolishBatch() : runPolish());
    } else if (taskId === 'rate') {
      result = await globalThis.__xyAutomation.enqueue(() => runRate(payload || {}));
    } else {
      result = { ok: false, reason: `未知任务 ${taskId}` };
    }
  } catch (e) {
    result = { ok: false, reason: String(e && e.message || e) };
  }
  ipcRenderer.send('task:result', { taskId, requestId, ...result });
});

// 调试用
window.__xyTask = { runPolish, runPolishBatch, runRate };

})();
